const body = $('Webhook: update-payment').first().json.body || {};
const id = parseInt(body.id, 10);
if (!Number.isInteger(id)) throw new Error('"id" is required.');

// Refunding or cancelling money movement is admin-only — status
// changes like marking paid/failed stay open to any rep.
const RESTRICTED_STATUSES = ['refunded', 'partially_refunded', 'cancelled'];
if (RESTRICTED_STATUSES.includes(body.status) && requester.role !== 'admin') {
  throw new Error('Admin access required to refund or cancel a payment.');
}

const VALID_STATUSES = ['pending', 'processing', 'paid', 'partially_paid', 'failed', 'refunded', 'partially_refunded', 'cancelled'];
if (body.status !== undefined && !VALID_STATUSES.includes(body.status)) throw new Error('Invalid status.');

return [{
  json: {
    id,
    status: body.status !== undefined ? body.status : null,
    amountReceived: body.amount_received !== undefined ? Number(body.amount_received) : null,
    refundedAmount: body.refunded_amount !== undefined ? Number(body.refunded_amount) : null,
    method: body.method !== undefined ? body.method : null,
    reference: body.reference !== undefined ? body.reference : null,
    paymentDate: body.payment_date !== undefined ? body.payment_date : null,
    dueDate: body.due_date !== undefined ? body.due_date : null,
    notes: body.notes !== undefined ? body.notes : null,
    ownerId: body.owner_id !== undefined ? (body.owner_id || null) : null,
    requesterId: requester.id,
    requesterName: requester.name,
  },
}];

const payload = $('Check Payload: update-payment').first().json;
const current = $input.first().json;
const changes = [];

if (payload.status !== null && payload.status !== current.status) {
  changes.push(`status changed from "${current.status}" to "${payload.status}"`);
}
if (payload.refundedAmount !== null && Number(payload.refundedAmount) !== Number(current.refunded_amount)) {
  changes.push(`refunded $${payload.refundedAmount}`);
}

const summary = changes.length > 0 ? `${payload.requesterName} ${changes.join(', ')}` : '';

return [{ json: { ...payload, hasChanges: changes.length > 0, changeSummary: summary } }];

