const invoiceItem = $('Postgres: Select Invoice Detail').first()?.json;
if (!invoiceItem || invoiceItem.id == null) throw new Error('Invoice not found.');

const payments = $('Postgres: Select Invoice Payments').all().filter((i) => i.json.id != null).map((i) => i.json);
const timeline = $('Postgres: Select Invoice Timeline').all().filter((i) => i.json.id != null).map((i) => i.json);
const relatedTickets = $('Postgres: Select Invoice Related Tickets').all().filter((i) => i.json.id != null).map((i) => i.json);

const amountPaid = payments.reduce((sum, p) => sum + Number(p.amount_received), 0) - payments.reduce((sum, p) => sum + Number(p.refunded_amount), 0);
let status;
if (invoiceItem.is_voided) status = 'voided';
else if (amountPaid >= Number(invoiceItem.total) && Number(invoiceItem.total) > 0) status = 'paid';
else if (amountPaid > 0) status = 'partially_paid';
else if (invoiceItem.due_date && new Date(invoiceItem.due_date) < new Date()) status = 'overdue';
else status = 'pending';

return [{
  json: {
    ...invoiceItem,
    status,
    amount_paid: amountPaid,
    outstanding: Number(invoiceItem.total) - amountPaid,
    payments,
    timeline,
    related_tickets: relatedTickets,
    is_admin: $('Check Requester: get-invoice').first().json.isAdmin,
  },
}];

