const payment = $('Postgres: Select Payment For Receipt').item.json;
const template = $input.first().json;
const hasTemplate = template && template.id != null;

function fill(text) {
  return (text || '')
    .replace(/{{\s*first_name\s*}}/gi, payment.contact_first_name || '')
    .replace(/{{\s*payment_number\s*}}/gi, payment.payment_number || '')
    .replace(/{{\s*amount\s*}}/gi, '$' + payment.amount_received)
    .replace(/{{\s*payment_date\s*}}/gi, payment.payment_date || '')
    .replace(/{{\s*deal_name\s*}}/gi, payment.deal_name || '');
}

const defaultSubject = `Receipt for payment ${payment.payment_number}`;
const defaultBody = `Hi ${payment.contact_first_name || ''},\n\nThis confirms your payment.\n\nPayment: ${payment.payment_number}\nAmount: $${payment.amount_received}\nDate: ${payment.payment_date || ''}${payment.deal_name ? '\nFor: ' + payment.deal_name : ''}\n\nThank you!`;

return [{
  json: {
    ...payment,
    receiptSubject: hasTemplate ? fill(template.subject) : defaultSubject,
    receiptBody: hasTemplate ? fill(template.body) : defaultBody,
  },
}];
